import { _decorator, Component, Node } from 'cc';
import { DEFAULT_GAME_CONFIG } from '../core/config';
import { PlatformSpec } from '../core/types';

const { ccclass, property } = _decorator;

/** Root = top center; collision metadata deliberately excludes the shadow. */
@ccclass('PlatformView')
export class PlatformView extends Component {
    @property(Node) visual: Node | null = null;
    @property modelKey = 'block_00';
    @property shape = 'rect';
    @property halfX = DEFAULT_GAME_CONFIG.platformWidth / 2;
    @property halfZ = DEFAULT_GAME_CONFIG.platformDepth / 2;
    @property radius = DEFAULT_GAME_CONFIG.platformWidth / 2;
    @property height = DEFAULT_GAME_CONFIG.platformHeight;
    @property horizontalScale = 1;

    spec: PlatformSpec | null = null;

    apply(spec: PlatformSpec): void {
        this.spec = spec; this.modelKey = spec.modelKey; this.shape = spec.shape;
        this.node.setPosition(spec.centerXZ.x, spec.topY, spec.centerXZ.z);
        this.halfX = spec.shape === 'rect' ? spec.halfExtent.x : spec.radius;
        this.halfZ = spec.shape === 'rect' ? spec.halfExtent.z : spec.radius;
        this.radius = spec.shape === 'circle' ? spec.radius : 0;
        this.setHorizontalScale(spec.horizontalScale);
    }
    resetForPool(): void {
        this.unscheduleAllCallbacks(); this.spec = null; this.modelKey = ''; this.shape = '';
        this.halfX = 0; this.halfZ = 0; this.radius = 0; this.horizontalScale = 1;
        this.node.setPosition(0, 0, 0); this.node.setRotationFromEuler(0, 0, 0); this.node.setScale(1, 1, 1);
        this.visual?.setScale(1, 1, 1); this.visual?.setPosition(0, -this.height / 2, 0);
    }

    setHorizontalScale(scale: number): void {
        if (!Number.isFinite(scale) || scale < DEFAULT_GAME_CONFIG.minPlatformScale || scale > DEFAULT_GAME_CONFIG.maxPlatformScale) {
            throw new RangeError('horizontalScale must be in [0.8, 1]');
        }
        this.horizontalScale = scale;
        this.visual?.setScale(scale, 1, scale);
    }
}

import { input, Input, EventKeyboard, EventMouse, EventTouch, KeyCode, game, Game, Node, UITransform, Button, EditBox, BlockInputEvents, Vec2 } from 'cc';

export interface InputSink {
    press(source: string): boolean;
    release(source: string): void;
    cancel(source?: string, reason?: string): void;
    pause(reason: string): void;
    command(key: KeyCode): void;
    blocked(): boolean;
}

/** The physical-down set is independent of gameplay owner; rejected busy inputs never become buffered presses. */
export class InputAdapter {
    private readonly down = new Set<string>();
    private owner: string | null = null;
    private bound = false;
    constructor(private readonly sink: InputSink, private readonly ui: Node) {}
    bind(): void {
        if (this.bound) return;
        this.bound = true;
        input.on(Input.EventType.KEY_DOWN, this.keyDown, this);
        input.on(Input.EventType.KEY_UP, this.keyUp, this);
        input.on(Input.EventType.MOUSE_DOWN, this.mouseDown, this);
        input.on(Input.EventType.MOUSE_UP, this.mouseUp, this);
        input.on(Input.EventType.TOUCH_START, this.touchDown, this);
        input.on(Input.EventType.TOUCH_END, this.touchUp, this);
        input.on(Input.EventType.TOUCH_CANCEL, this.touchCancel, this);
        game.on(Game.EVENT_HIDE, this.hide, this);
        if (typeof window !== 'undefined') window.addEventListener('blur', this.blur);
        if (typeof document !== 'undefined') document.addEventListener('visibilitychange', this.visibility);
    }
    unbind(): void {
        if (!this.bound) return;
        this.bound = false;
        input.off(Input.EventType.KEY_DOWN, this.keyDown, this);
        input.off(Input.EventType.KEY_UP, this.keyUp, this);
        input.off(Input.EventType.MOUSE_DOWN, this.mouseDown, this);
        input.off(Input.EventType.MOUSE_UP, this.mouseUp, this);
        input.off(Input.EventType.TOUCH_START, this.touchDown, this);
        input.off(Input.EventType.TOUCH_END, this.touchUp, this);
        input.off(Input.EventType.TOUCH_CANCEL, this.touchCancel, this);
        game.off(Game.EVENT_HIDE, this.hide, this);
        if (typeof window !== 'undefined') window.removeEventListener('blur', this.blur);
        if (typeof document !== 'undefined') document.removeEventListener('visibilitychange', this.visibility);
        this.reset(); this.down.clear();
    }
    reset(): void { this.sink.cancel(this.owner || undefined, 'input-reset'); this.owner = null; }
    private begin(source: string, blocked: boolean): void {
        if (this.down.has(source)) return;
        this.down.add(source);
        if (!blocked && !this.sink.blocked() && this.owner === null && this.sink.press(source)) this.owner = source;
    }
    private end(source: string, cancel = false): void {
        this.down.delete(source);
        if (this.owner !== source) return;
        this.owner = null;
        if (cancel) this.sink.cancel(source, 'touch-cancel'); else this.sink.release(source);
    }
    private keyDown(event: EventKeyboard): void {
        if (event.keyCode === KeyCode.SPACE) this.begin('space', this.formFocused());
        else {
            const source = `key:${event.keyCode}`;
            if (!this.down.has(source) && !this.formFocused()) { this.down.add(source); this.sink.command(event.keyCode); }
        }
    }
    private keyUp(event: EventKeyboard): void {
        if (event.keyCode === KeyCode.SPACE) this.end('space'); else this.down.delete(`key:${event.keyCode}`);
    }
    private mouseDown(event: EventMouse): void { if (event.getButton() === 0) this.begin('mouse-left', this.hitUI(event.getLocation())); }
    private mouseUp(event: EventMouse): void { if (event.getButton() === 0) this.end('mouse-left'); }
    private touchDown(event: EventTouch): void { this.begin(`touch:${event.getID()}`, this.hitUI(event.getLocation())); }
    private touchUp(event: EventTouch): void { this.end(`touch:${event.getID()}`); }
    private touchCancel(event: EventTouch): void { this.end(`touch:${event.getID()}`, true); }
    private hitUI(point: Vec2): boolean {
        const nodes = this.ui.getComponentsInChildren(UITransform);
        return nodes.some(ui => ui.node.activeInHierarchy && (
            ui.getComponent(Button)?.enabled || ui.getComponent(EditBox)?.enabled || ui.getComponent(BlockInputEvents)?.enabled
        ) && ui.hitTest(point));
    }
    private formFocused(): boolean {
        if (typeof document === 'undefined') return false;
        const element = document.activeElement as HTMLElement | null;
        return !!element && (element.tagName === 'INPUT' || element.tagName === 'TEXTAREA' || element.isContentEditable);
    }
    private hide(): void { this.reset(); this.sink.pause('background'); }
    private readonly blur = (): void => { this.reset(); this.sink.pause('blur'); };
    private readonly visibility = (): void => { if (document.hidden) this.hide(); };
}

import { instantiate, Node, Prefab, Tween, MeshRenderer, Material } from 'cc';
import { ModelKey, PlatformSpec } from '../core/types';
import { PlatformView } from './PlatformView';
interface Slot {
    node: Node; view: PlatformView; id: number | null; model: ModelKey | null;
    materials: { renderer: MeshRenderer; shared: (Material | null)[] }[];
}

/** Bounded wrapper pool. Only view instances own state; imported assets stay read-only. */
export class PlatformPool {
    private readonly slots: Slot[] = [];
    constructor(private readonly parent: Node, private readonly rect: Prefab, private readonly rect01: Prefab,
        private readonly circle: Prefab, private readonly models: readonly Prefab[], private readonly keys: readonly ModelKey[], private readonly limit: number) {
        if (models.length !== keys.length) throw new Error('10 explicit model Prefabs required');
    }
    sync(specs: readonly PlatformSpec[]): void {
        if (specs.length > this.limit) throw new Error('platform pool limit exceeded');
        const wanted = new Set(specs.map(s => s.id));
        for (const slot of this.slots) if (slot.id !== null && !wanted.has(slot.id)) this.recycle(slot);
        for (const spec of specs) {
            let slot = this.slots.find(s => s.id === spec.id);
            if (!slot) {
                slot = this.slots.find(s => s.id === null);
                if (!slot) {
                    if (this.slots.length >= this.limit) throw new Error('no free platform slot');
                    const prefab = spec.modelKey === 'block_03' ? this.circle : spec.modelKey === 'block_01' ? this.rect01 : this.rect;
                    const node = instantiate(prefab); this.parent.addChild(node);
                    const view = node.getComponent(PlatformView);
                    if (!view || !view.visual) throw new Error('stage01 PlatformView/Visual missing');
                    slot = { node, view, id: null, model: null, materials: [] }; this.slots.push(slot);
                }
                if (slot.model !== spec.modelKey) this.setModel(slot, spec.modelKey);
                slot.id = spec.id; slot.node.name = `Platform_${spec.id}_${spec.modelKey}`; slot.node.active = true;
            }
            slot.view.apply(spec);
        }
    }
    get count(): number { return this.slots.length; }
    clear(): void { this.slots.forEach(slot => this.recycle(slot)); }
    destroy(): void { this.slots.forEach(slot => slot.node.destroy()); this.slots.length = 0; }
    private setModel(slot: Slot, model: ModelKey): void {
        const visual = slot.view.visual!;
        for (const child of [...visual.children]) { child.removeFromParent(); child.destroy(); }
        const prefab = this.models[this.keys.indexOf(model)];
        if (!prefab) throw new Error(`missing model ${model}`);
        visual.addChild(instantiate(prefab)); slot.model = model;
        slot.materials = slot.node.getComponentsInChildren(MeshRenderer).map(renderer => ({ renderer, shared: [...renderer.sharedMaterials] }));
    }
    private recycle(slot: Slot): void {
        const stop = (node: Node): void => { Tween.stopAllByTarget(node); node.children.forEach(stop); };
        stop(slot.node);
        for (const entry of slot.materials) entry.shared.forEach((material, index) => entry.renderer.setSharedMaterial(material, index));
        slot.view.resetForPool(); slot.id = null; slot.node.active = false;
    }
}

